function check(input, actual, expected) {
  const s = input[0];
  const n = s.length;
  if (!Array.isArray(actual) || actual.length !== n + 1) return false;
  const seen = new Array(n + 1).fill(false);
  for (const value of actual) {
    if (!Number.isInteger(value) || value < 0 || value > n || seen[value]) return false;
    seen[value] = true;
  }
  for (let i = 0; i < n; i++) {
    if (s[i] === 'I' ? !(actual[i] < actual[i + 1]) : !(actual[i] > actual[i + 1])) return false;
  }
  return true;
}

