function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 100000 letters.';
  if (!/^[ID]+$/.test(s)) return "s may only contain 'I' and 'D'.";
  return null;
}

