function diStringMatch(s) {
  let low = 0;
  let high = s.length;
  const perm = [];

  for (const ch of s) {
    if (ch === 'I') {
      perm.push(low);
      low++;
    } else {
      perm.push(high);
      high--;
    }
  }
  perm.push(low);
  return perm;
}

