function diStringMatch(s) {
  // Start from 0..n in order (every 'I' holds) and reverse each block covered by a run of 'D's.
  const perm = Array.from({ length: s.length + 1 }, (_, i) => i);
  let i = 0;
  while (i < s.length) {
    if (s[i] !== 'D') { i++; continue; }
    let j = i;
    while (j < s.length && s[j] === 'D') j++;
    const block = perm.slice(i, j + 1).reverse();
    for (let k = 0; k < block.length; k++) perm[i + k] = block[k];
    i = j;
  }
  return perm;
}

