function generate(rand, size) {
  const n = size === 'large' ? 8000 + Math.floor(rand() * 2001) : 1 + Math.floor(rand() * 10);
  // A bias toward the previous letter makes long runs of 'I' or 'D' as well as alternations.
  const stick = rand();
  let s = rand() < 0.5 ? 'I' : 'D';
  while (s.length < n) {
    const last = s[s.length - 1];
    s += rand() < stick ? last : (last === 'I' ? 'D' : 'I');
  }
  return [s];
}
